import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to “隐私政策”">​</a></h1><p>Sudoku 是一款以离线为先的应用，云功能均为可选。本页说明应用会收集哪些数据（如果有），以及这些数据的使用方式。</p><h2 id="离线核心——游玩过程不收集任何数据" tabindex="-1">离线核心——游玩过程不收集任何数据 <a class="header-anchor" href="#离线核心——游玩过程不收集任何数据" aria-label="Permalink to “离线核心——游玩过程不收集任何数据”">​</a></h2><ul><li>核心解谜玩法完全可离线进行，游玩不需要任何网络访问。</li><li>所有游戏数据——设置、游戏状态、铅笔笔记和统计数据——都存储在您的设备本地。</li><li>没有广告，没有数据分析，也没有第三方追踪 SDK。</li></ul><h2 id="可选的云功能" tabindex="-1">可选的云功能 <a class="header-anchor" href="#可选的云功能" aria-label="Permalink to “可选的云功能”">​</a></h2><h3 id="icloud-同步-cloudkit" tabindex="-1">iCloud 同步（CloudKit） <a class="header-anchor" href="#icloud-同步-cloudkit" aria-label="Permalink to “iCloud 同步（CloudKit）”">​</a></h3><p>当您登录 iCloud 并启用同步时：</p><ul><li>游戏存档、统计数据、设置和每日挑战进度会通过 Apple 的 CloudKit 服务同步到您<strong>个人的 iCloud 账户</strong>。</li><li>数据在传输和存储过程中由 Apple 的基础设施加密。</li><li>只有您本人能通过自己的 Apple ID 访问已同步的数据。</li><li>此功能完全可选——即使不启用，应用也能正常使用。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>当您登录 Game Center 时：</p><ul><li>排行榜成绩（各难度的最佳完成时间）可能会在公开排行榜上展示。</li><li>成就进度由 Apple 的 Game Center 服务记录。</li><li>您的 Game Center 显示名称会向排行榜上的其他玩家可见。</li><li>此功能完全可选。</li></ul><h2 id="唯一的其他网络访问-更多-app" tabindex="-1">唯一的其他网络访问：“更多 App” <a class="header-anchor" href="#唯一的其他网络访问-更多-app" aria-label="Permalink to “唯一的其他网络访问：“更多 App””">​</a></h2><p>唯一的非云端网络功能，是设置中可选的 <strong>“更多 App”</strong> 板块，它会从我们的服务器获取同系列应用的列表。此功能：</p><ul><li>仅在您进入“设置 → 更多 App”时才会启用。</li><li>只获取一份轻量的应用名称与链接列表——不会发送或存储任何个人数据。</li><li>完全可以忽略，且不会以任何方式影响游戏体验。</li></ul><h2 id="我们不会收集的信息" tabindex="-1">我们不会收集的信息 <a class="header-anchor" href="#我们不会收集的信息" aria-label="Permalink to “我们不会收集的信息”">​</a></h2><ul><li>我们不收集个人信息、文件、图像或浏览历史。</li><li>我们不会将任何游戏数据发送到外部服务器（上文所述的 iCloud/Game Center 情形除外）。</li><li>我们不包含第三方数据分析或广告 SDK。</li><li>我们不使用崩溃报告或遥测服务。</li></ul><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to “权限”">​</a></h2><p>Sudoku 所需的权限极少：</p><ul><li><strong>iCloud</strong>（可选）：用于通过 CloudKit 在设备间同步游戏数据。</li><li><strong>Game Center</strong>（可选）：用于排行榜和成就。</li><li><strong>网络</strong>（可选）：用于 iCloud 同步、Game Center 和“更多 App”。</li></ul><p>不会请求定位、通讯录、相机、麦克风或其他涉及隐私的敏感权限。</p><h2 id="数据保留" tabindex="-1">数据保留 <a class="header-anchor" href="#数据保留" aria-label="Permalink to “数据保留”">​</a></h2><ul><li>本地数据会一直保留在您的设备上，直到您卸载或重置应用。</li><li>iCloud 同步的数据遵循 Apple 的 iCloud 数据保留政策。</li><li>Game Center 数据遵循 Apple 的 Game Center 相关政策。</li></ul><h2 id="隐私相关请求" tabindex="-1">隐私相关请求 <a class="header-anchor" href="#隐私相关请求" aria-label="Permalink to “隐私相关请求”">​</a></h2><p>由于 Sudoku 将所有数据存储在本地（并可选存储在您个人的 iCloud 中），我们并不控制或访问任何服务器端数据。如需清除应用的全部数据：</p><ul><li><strong>卸载应用</strong>：从您的设备上卸载。</li><li><strong>重置 iCloud 数据</strong>：进入“设置 → [你的名字] → iCloud → 管理账户储存空间 → Sudoku → 删除数据”。</li><li><strong>重置 Mac 本地数据</strong>：删除容器的具体步骤请参阅故障排查指南。</li></ul><h2 id="儿童隐私" tabindex="-1">儿童隐私 <a class="header-anchor" href="#儿童隐私" aria-label="Permalink to “儿童隐私”">​</a></h2><p>Sudoku 不会主动收集任何人（包括儿童）的个人信息。本应用不需要账户，也不包含聊天或社交网络功能。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to “联系我们”">​</a></h2><p>如对隐私有任何疑问，请在项目仓库（<a href="https://github.com/sudoku-pro/sudoku-site%EF%BC%89%E6%8F%90%E4%BA%A4" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site）提交</a> issue，或通过 <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a> 与我们联系。</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};